create type public.scorekeeper_mode as enum ('traditional','control_point');
create type public.scorekeeper_user_role as enum ('admin','management');
create table public."tControlPointMatch" (id uuid not null default gen_random_uuid(),owner_id uuid not null,mode scorekeeper_mode not null default 'control_point'::scorekeeper_mode,event_id uuid,round_name text not null default ''::text,team_a_id uuid,team_b_id uuid,team_a_name text not null default 'Team A'::text,team_b_name text not null default 'Team B'::text,duration_ms integer,remaining_ms integer,phase text not null default 'ready'::text,end_reason text,created_at timestamp with time zone not null default now(),started_at timestamp with time zone,ended_at timestamp with time zone,updated_at timestamp with time zone not null default now());
create table public."tControlPointTime" (id uuid not null default gen_random_uuid(),owner_id uuid not null,match_id uuid not null,point_key text not null default 'main'::text,team_id uuid,start_ms integer not null,end_ms integer,notes text not null default ''::text,recorded_at timestamp with time zone not null default now(),mode scorekeeper_mode not null default 'control_point'::scorekeeper_mode);
create table public."tEvent" (id uuid not null default gen_random_uuid(),owner_id uuid not null,name text not null,mode scorekeeper_mode not null,starts_at timestamp with time zone,ends_at timestamp with time zone,description text not null default ''::text,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now());
create table public."tEventTeam" (event_id uuid not null,team_id uuid not null,owner_id uuid not null,mode scorekeeper_mode not null,added_at timestamp with time zone not null default now());
create table public."tFencer" (id uuid not null default gen_random_uuid(),owner_id uuid not null,display_name text not null,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now());
create table public."tMatchPreset" (id uuid not null default gen_random_uuid(),owner_id uuid not null,name text not null,mode scorekeeper_mode not null default 'traditional'::scorekeeper_mode,duration_ms integer not null default 180000,target_score integer,is_default boolean not null default false,settings jsonb not null default '{}'::jsonb,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now());
create table public."tTeam" (id uuid not null default gen_random_uuid(),owner_id uuid not null,name text not null,mode scorekeeper_mode not null,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now());
create table public."tTeamFencer" (team_id uuid not null,fencer_id uuid not null,owner_id uuid not null,added_at timestamp with time zone not null default now());
create table public."tTraditionalCall" (id uuid not null default gen_random_uuid(),match_id uuid not null,side text not null,call_type text not null,points smallint not null,match_time_ms integer not null,recorded_at timestamp with time zone not null default now(),created_at timestamp with time zone not null default now());
create table public."tTraditionalMatch" (id uuid not null default gen_random_uuid(),owner_id uuid not null,event_name text not null default ''::text,round_name text not null default ''::text,left_fencer_id uuid,right_fencer_id uuid,left_name text not null default 'Fencer A'::text,right_name text not null default 'Fencer B'::text,duration_ms integer not null default 180000,remaining_ms integer not null default 180000,target_score integer,phase text not null default 'ready'::text,end_reason text,created_at timestamp with time zone not null default now(),started_at timestamp with time zone,ended_at timestamp with time zone,updated_at timestamp with time zone not null default now(),mode scorekeeper_mode not null default 'traditional'::scorekeeper_mode,event_id uuid);
create table public."tUser" (id uuid not null,email text not null,display_name text not null default ''::text,app_role scorekeeper_user_role not null default 'management'::scorekeeper_user_role,is_active boolean not null default true,must_change_password boolean not null default false,created_by uuid,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now());
create table public."tControlPointCall" (id uuid not null default gen_random_uuid(),owner_id uuid not null,match_id uuid not null,fencer_id uuid,team_id uuid,call_type text not null,point_delta integer not null default 0,match_time_ms integer not null,notes text not null default ''::text,recorded_at timestamp with time zone not null default now(),mode scorekeeper_mode not null default 'control_point'::scorekeeper_mode);
alter table "tTraditionalMatch" add constraint traditional_match_id_owner_uq UNIQUE (id, owner_id);
